const story = $('Fetch Approved Stories').first().json;
const fetched = $('Fetch Linked Assets').all().map(x => x.json);
const downloaded = $input.all().map(x => x.json);
const byIndex = new Map();
for (let i = 0; i < fetched.length; i++) {
  const a = { ...fetched[i], imageBase64: (downloaded[i] && downloaded[i].imageBase64) || '' };
  const idx = Number(a['Slide Index']);
  if (idx >= 1 && idx <= 7) byIndex.set(idx, a);
}
const assets = [...byIndex.entries()].sort((a, b) => a[0] - b[0]).map(([, a]) => a);
if (assets.length === 0) throw new Error('No Assets with Slide Index 1-7 found for Story ' + story.id);
return [{
  json: {
    storyId: story.id,
    title: story.Title,
    pillar: story.Pillar,
    story,
    assets,
    xThread: {
      post1: (story.Title || '') + ' — ' + (story.Glance || ''),
      post2: (story.Remember || '') + ' (1/2 → 2/2)'
    }
  }
}];

// #!/usr/bin/env node
"use strict";

function esc(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function splitSentences(text) {
  return String(text || "").trim().replace(/\s+/g, " ").split(/(?<=[.!?])\s+/).filter(Boolean);
}

function fitCompleteSentences(text, maxWords) {
  const sentences = splitSentences(text);
  if (!sentences.length) return String(text || "").trim();
  const kept = [];
  let count = 0;
  for (const s of sentences) {
    const words = s.replace(/\*\*/g, "").split(/\s+/).filter(Boolean).length;
    if (kept.length === 0 || count + words <= maxWords) {
      kept.push(s);
      count += words;
    } else {
      break;
    }
  }
  return kept.join(" ");
}

function tokenizeRichWords(text) {
  const rawWords = String(text || "").trim().split(/\s+/).filter(Boolean);
  const tokens = [];
  let inBold = false;
  for (const rw of rawWords) {
    let w = rw;
    let bold = inBold;
    if (w.startsWith("**")) {
      bold = true;
      w = w.slice(2);
    }
    let endsBold = false;
    if (w.endsWith("**")) {
      endsBold = true;
      w = w.slice(0, -2);
    }
    if (w.includes("**")) {
      w = w.replace(/\*\*/g, "");
    }
    if (w) tokens.push({ text: w, bold });
    inBold = endsBold ? false : (rw.startsWith("**") && !rw.slice(2).includes("**") ? true : (endsBold ? false : inBold));
    if (rw.startsWith("**") && rw.endsWith("**") && rw.length > 4) inBold = false;
  }
  return tokens;
}

function wrapRichLines(text, maxChars, maxLines) {
  const tokens = tokenizeRichWords(text);
  const lines = [];
  let curTokens = [];
  let curLen = 0;
  for (const tok of tokens) {
    const addLen = (curLen ? 1 : 0) + tok.text.length;
    if (!curLen || curLen + addLen <= maxChars) {
      curTokens.push(tok);
      curLen += addLen;
    } else {
      lines.push(curTokens);
      curTokens = [tok];
      curLen = tok.text.length;
      if (maxLines && lines.length >= maxLines) break;
    }
  }
  if (curTokens.length && (!maxLines || lines.length < maxLines)) {
    lines.push(curTokens);
  }
  return lines;
}

function renderRichTspans(lineTokens, accentColor) {
  const spans = [];
  for (let i = 0; i < lineTokens.length; i++) {
    const tok = lineTokens[i];
    const prefix = i === 0 ? "" : " ";
    if (tok.bold) {
      spans.push(`<tspan font-weight="700" fill="${accentColor}">${esc(prefix + tok.text)}</tspan>`);
    } else {
      spans.push(esc(prefix + tok.text));
    }
  }
  return spans.join("");
}

function buildParagraphBlocks(paragraphs, maxChars, maxTotalLines) {
  const blocks = [];
  let used = 0;
  for (const p of paragraphs) {
    const clean = String(p || "").trim();
    if (!clean) continue;
    const remaining = maxTotalLines - used;
    if (remaining <= 0) break;
    const lines = wrapRichLines(clean, maxChars, remaining);
    if (lines.length) {
      blocks.push(lines);
      used += lines.length;
    }
  }
  return blocks;
}

function parsePolishedCopy(rawItem) {
  if (!rawItem || rawItem.error) return null;
  let obj = rawItem;
  if (!Array.isArray(obj.slides)) {
    const rawText = (obj.content?.parts?.map(p => p.text || "").join("") || obj.text || obj.output || "").replace(/```(?:json)?/g, "").trim();
    if (!rawText) return null;
    try {
      obj = JSON.parse(rawText);
    } catch {
      return null;
    }
  }
  if (!obj || !Array.isArray(obj.slides) || obj.slides.length < 4) return null;
  return obj;
}

function buildNarrativeSections(story, count) {
  const glanceSentences = splitSentences(story.Glance);
  const exploreParas = String(story.Explore || "").split(/\n+/).map(s => s.trim()).filter(Boolean);
  const deepParas = String(story["Deep Dive"] || "").split(/\n+/).map(s => s.trim()).filter(Boolean);
  const rememberText = String(story.Remember || "").trim();

  const coverSubtitle = glanceSentences[0] || "";
  const sections = [
    { kind: "cover", heading: String(story.Title || "").trim(), paragraphs: coverSubtitle ? [coverSubtitle] : [] }
  ];

  const bodyPool = [];
  if (glanceSentences.length > 1) {
    bodyPool.push({ heading: "Built to Outlast", paragraphs: [fitCompleteSentences(glanceSentences.slice(1).join(" "), 40)] });
  }
  for (const p of exploreParas) {
    const sents = splitSentences(p);
    if (sents.length >= 4) {
      const mid = Math.ceil(sents.length / 2);
      bodyPool.push({ heading: "How It Worked", paragraphs: [fitCompleteSentences(sents.slice(0, mid).join(" "), 40)] });
      bodyPool.push({ heading: "Why It Mattered", paragraphs: [fitCompleteSentences(sents.slice(mid).join(" "), 40)] });
    } else {
      bodyPool.push({ heading: "How It Worked", paragraphs: [fitCompleteSentences(p, 40)] });
    }
  }
  for (const p of deepParas) {
    const sents = splitSentences(p);
    if (sents.length >= 4) {
      const mid = Math.ceil(sents.length / 2);
      bodyPool.push({ heading: "The Clever Detail", paragraphs: [fitCompleteSentences(sents.slice(0, mid).join(" "), 40)] });
      bodyPool.push({ heading: "Precision in Practice", paragraphs: [fitCompleteSentences(sents.slice(mid).join(" "), 40)] });
    } else {
      bodyPool.push({ heading: "The Clever Detail", paragraphs: [fitCompleteSentences(p, 40)] });
    }
  }

  const middleSlots = Math.max(0, count - 2);
  for (let i = 0; i < middleSlots; i++) {
    sections.push(bodyPool[i] || { heading: String(story.Title || "The Story"), paragraphs: [fitCompleteSentences(story.Explore || story.Glance || "", 40)] });
  }

  if (count >= 2) {
    sections.push({
      kind: "legacy",
      heading: "What Still Endures",
      paragraphs: [fitCompleteSentences(rememberText || story.Glance || "", 40)],
      cta: "Save this · Which ancient tech should we cover next?"
    });
  }

  return sections.slice(0, count);
}

function buildCarouselSlides(story, assets, polished) {
  if (!story || !story.Title) throw new Error("Missing Story Title");
  const byIndex = new Map();
  for (const a of (assets || [])) {
    const idx = Number(a["Slide Index"]);
    if (idx >= 1 && idx <= 7) byIndex.set(idx, a);
  }
  const maxAssetIdx = byIndex.size ? Math.max(...byIndex.keys()) : 0;
  const totalSlides = Math.max(4, maxAssetIdx || 6);
  const fallbackSections = buildNarrativeSections(story, totalSlides);
  const polishedByIdx = new Map();
  if (polished && Array.isArray(polished.slides)) {
    for (const ps of polished.slides) {
      polishedByIdx.set(Number(ps.slide_index), ps);
    }
  }

  const slides = [];
  for (let i = 1; i <= totalSlides; i++) {
    const asset = byIndex.get(i) || null;
    const ps = polishedByIdx.get(i) || null;
    const sec = fallbackSections[i - 1] || { kind: "body", heading: story.Title, paragraphs: [] };
    const hasPhoto = Boolean(asset && (asset.imageBase64 || (Array.isArray(asset.File) && asset.File[0] && asset.File[0].url)));
    const isCover = i === 1;
    const isLast = i === totalSlides;
    const heading = (ps && ps.headline) ? String(ps.headline) : sec.heading;
    const bodyText = (ps && ps.body) ? String(ps.body) : sec.paragraphs.join(" ");
    const cta = isLast ? ((polished && polished.cta) || sec.cta || "Save this · Which ancient tech should we cover next?") : "";
    slides.push({
      slideIndex: i,
      totalSlides,
      kind: isCover ? "cover" : isLast ? "legacy" : "body",
      style: hasPhoto ? (asset.style || "photo") : "card",
      pillar: String(story.Pillar || "WE, HUMANITY").toUpperCase(),
      heading,
      paragraphs: bodyText ? [bodyText] : [],
      cta,
      credit: asset ? asset.Credit : "",
      license: asset ? (asset.License || "") : "",
      aiGenerated: Boolean(asset && asset["AI Generated"]),
      imageBase64: asset ? (asset.imageBase64 || "") : "",
      imageMime: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].type) || "image/jpeg",
      imageUrl: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].url) || ""
    });
  }
  return slides;
}

function renderSlideSvg(slide) {
  const slideCounter = String(slide.slideIndex).padStart(2, "0") + " / " + String(slide.totalSlides).padStart(2, "0");
  const swipeBadge = slide.slideIndex === 1
    ? `<g transform="translate(836, 1216)">
        <rect x="0" y="0" width="164" height="44" rx="22" fill="#0B0B0A" fill-opacity="0.62" stroke="#FFFFFF" stroke-opacity="0.45" stroke-width="1.5"/>
        <text x="82" y="29" text-anchor="middle" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="19" font-weight="700" letter-spacing="1">Swipe →</text>
      </g>`
    : "";

  if (slide.style === "card") {
    const headingLines = wrapRichLines(slide.heading, 24, 4);
    const paraBlocks = buildParagraphBlocks(slide.paragraphs, 44, 12);
    const headLH = 62;
    const bodyLH = 46;
    const paraGap = 24;

    let bodyLinesCount = 0;
    for (const b of paraBlocks) bodyLinesCount += b.length;
    const bodyH = bodyLinesCount * bodyLH + Math.max(0, paraBlocks.length - 1) * paraGap;
    const ctaH = slide.cta ? 56 : 0;
    const totalH = headingLines.length * headLH + 28 + bodyH + ctaH;
    const startY = Math.max(220, Math.round((1350 - totalH) / 2));

    const headEls = headingLines.map((l, i) =>
      `<text x="84" y="${startY + i * headLH}" fill="#171715" font-family="Helvetica Neue, Inter, sans-serif" font-size="52" font-weight="700" letter-spacing="-0.8">${renderRichTspans(l, "#1D4ED8")}</text>`
    ).join("\n  ");

    let curY = startY + headingLines.length * headLH + 34;
    const bodyEls = [];
    for (const block of paraBlocks) {
      for (const line of block) {
        bodyEls.push(`<text x="84" y="${curY}" fill="#2F2F2B" font-family="Helvetica Neue, Inter, sans-serif" font-size="33" font-weight="400">${renderRichTspans(line, "#1D4ED8")}</text>`);
        curY += bodyLH;
      }
      curY += paraGap;
    }
    if (slide.cta) {
      bodyEls.push(`<text x="84" y="${curY + 14}" fill="#1D4ED8" font-family="Helvetica Neue, Inter, sans-serif" font-size="25" font-weight="700">${esc(slide.cta)}</text>`);
    }

    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <rect width="1080" height="1350" fill="#F6F4EF"/>
  <rect x="36" y="36" width="1008" height="1278" rx="16" fill="none" stroke="#DDD8CC" stroke-width="2"/>
  <text x="84" y="96" fill="#1D4ED8" font-family="Helvetica Neue, Inter, sans-serif" font-size="18" font-weight="700" letter-spacing="2">${esc(slide.pillar)}</text>
  <text x="996" y="96" text-anchor="end" fill="#5E5D58" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="600" letter-spacing="2">${esc(slideCounter)}</text>
  ${headEls}
  ${bodyEls.join("\n  ")}
  <text x="84" y="1274" fill="#171715" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="700" letter-spacing="2">WE, HUMANITY</text>
  ${swipeBadge}
</svg>`;
  }

  const imgHref = slide.imageBase64
    ? ("data:" + slide.imageMime + ";base64," + slide.imageBase64)
    : (slide.imageUrl ? esc(slide.imageUrl) : "");

  const creditText = slide.aiGenerated ? "Visual synthesis via Gemini Flash Image (WE, HUMANITY)" : slide.credit;
  const creditShort = creditText ? (creditText.length > 88 ? creditText.slice(0, 85) + "..." : creditText) : "";

  let textSvg = "";
  if (slide.kind === "cover") {
    const titleLines = wrapRichLines(slide.heading, 20, 4);
    const subLines = slide.paragraphs[0] ? wrapRichLines(slide.paragraphs[0], 46, 4) : [];
    const titleLH = 74;
    const subLH = 40;
    const totalH = titleLines.length * titleLH + (subLines.length ? 22 + subLines.length * subLH : 0);
    const startY = Math.max(540, 1185 - totalH);

    const titleEls = titleLines.map((l, i) =>
      `<text x="80" y="${startY + i * titleLH}" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="64" font-weight="700" letter-spacing="-1.2" filter="url(#textShadow)">${renderRichTspans(l, "#F5B841")}</text>`
    ).join("\n  ");

    const subStartY = startY + titleLines.length * titleLH + 22;
    const subEls = subLines.map((l, i) =>
      `<text x="80" y="${subStartY + i * subLH}" fill="#F3F1EC" fill-opacity="0.96" font-family="Helvetica Neue, Inter, sans-serif" font-size="29" font-weight="400" filter="url(#textShadow)">${renderRichTspans(l, "#F5B841")}</text>`
    ).join("\n  ");

    textSvg = titleEls + "\n  " + subEls + "\n  " + swipeBadge;
  } else {
    const headingLines = wrapRichLines(slide.heading, 24, 3);
    const paraBlocks = buildParagraphBlocks(slide.paragraphs, 40, 10);
    const headLH = 58;
    const bodyLH = 43;
    const paraGap = 18;

    let bodyLinesCount = 0;
    for (const b of paraBlocks) bodyLinesCount += b.length;
    const bodyH = bodyLinesCount * bodyLH + Math.max(0, paraBlocks.length - 1) * paraGap;
    const ctaH = slide.cta ? 56 : 0;
    const totalH = headingLines.length * headLH + 22 + bodyH + ctaH;
    const startY = Math.max(440, 1215 - totalH);

    const headEls = headingLines.map((l, i) =>
      `<text x="80" y="${startY + i * headLH}" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="48" font-weight="700" letter-spacing="-0.6" filter="url(#textShadow)">${renderRichTspans(l, "#F5B841")}</text>`
    ).join("\n  ");

    let curY = startY + headingLines.length * headLH + 28;
    const bodyEls = [];
    for (const block of paraBlocks) {
      for (const line of block) {
        bodyEls.push(`<text x="80" y="${curY}" fill="#F5F3EE" fill-opacity="0.97" font-family="Helvetica Neue, Inter, sans-serif" font-size="31" font-weight="400" filter="url(#textShadow)">${renderRichTspans(line, "#F5B841")}</text>`);
        curY += bodyLH;
      }
      curY += paraGap;
    }
    if (slide.cta) {
      const ctaLines = wrapRichLines(slide.cta, 46, 2);
      curY += 8;
      for (const cl of ctaLines) {
        bodyEls.push(`<text x="80" y="${curY}" fill="#F5B841" font-family="Helvetica Neue, Inter, sans-serif" font-size="25" font-weight="700" filter="url(#textShadow)">${renderRichTspans(cl, "#FFFFFF")}</text>`);
        curY += 34;
      }
    }

    textSvg = headEls + "\n  " + bodyEls.join("\n  ");
  }

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <defs>
    <linearGradient id="editorialScrim" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="#0B0B0A" stop-opacity="0.45"/>
      <stop offset="28%" stop-color="#0B0B0A" stop-opacity="0.06"/>
      <stop offset="50%" stop-color="#0B0B0A" stop-opacity="0.68"/>
      <stop offset="76%" stop-color="#0B0B0A" stop-opacity="0.91"/>
      <stop offset="100%" stop-color="#0B0B0A" stop-opacity="0.97"/>
    </linearGradient>
    <filter id="textShadow" x="-10%" y="-10%" width="120%" height="120%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.72"/>
    </filter>
  </defs>
  <rect width="1080" height="1350" fill="#181816"/>
  ${imgHref ? `<image href="${imgHref}" x="0" y="0" width="1080" height="1350" preserveAspectRatio="xMidYMid slice"/>` : ""}
  <rect width="1080" height="1350" fill="url(#editorialScrim)"/>
  ${slide.slideIndex === 1 ? `<text x="80" y="88" fill="#FFFFFF" font-family="Helvetica Neue, Inter, sans-serif" font-size="26" font-weight="700" letter-spacing="3" filter="url(#textShadow)">WH</text>` : ""}
  <text x="1000" y="88" text-anchor="end" fill="#FFFFFF" fill-opacity="0.88" font-family="Helvetica Neue, Inter, sans-serif" font-size="22" font-weight="600" letter-spacing="2" filter="url(#textShadow)">${esc(slideCounter)}</text>
  ${textSvg}
  ${creditShort ? `<text x="80" y="1312" fill="#E6E4DF" fill-opacity="0.78" font-family="Helvetica Neue, Inter, sans-serif" font-size="14" filter="url(#textShadow)">${esc(creditShort)}</text>` : ""}
</svg>`;
}

const payload = $("Validate & Build Carousel Payload").first().json;
const polished = parsePolishedCopy($input.first().json);
const slides = buildCarouselSlides(payload.story, payload.assets, polished);
const credits = slides.filter(s => s.credit).map(s => `${s.slideIndex}. ${s.credit}`).join("\n");
const pillarTag = "#" + String(payload.pillar || "History").replace(/[^a-zA-Z0-9]+/g, "");
const fallbackTags = `#WeHumanity #HistoryOfDesign #EngineeringHistory ${pillarTag}`.trim();
const linkedinCaption = (polished && polished.linkedin_caption)
  ? `${polished.linkedin_caption}${credits ? `\n\nCredits:\n${credits}` : ""}`
  : `${payload.title}: ${payload.story.Glance || ""}\n\n${payload.story.Remember || ""}${credits ? `\n\nCredits:\n${credits}` : ""}`;
const instagramCaption = (polished && polished.instagram_caption)
  ? polished.instagram_caption
  : `How ${payload.title} worked — and why it still matters.\n\n${payload.story.Glance || ""}${payload.story.Remember ? `\n\n${payload.story.Remember}` : ""}\n\nSave this for later. Which ancient invention should we cover next?\n\n${fallbackTags}`;
const xThread = (polished && polished.x_post_1 && polished.x_post_2)
  ? { post1: polished.x_post_1, post2: polished.x_post_2 }
  : payload.xThread;

const out = [];
for (const s of slides) {
  const svg = renderSlideSvg(s);
  const filename = `${payload.storyId}_slide_${s.slideIndex}.svg`;
  out.push({
    json: {
      storyId: payload.storyId,
      slideIndex: s.slideIndex,
      title: payload.title,
      pillar: payload.pillar,
      svg,
      filename,
      localPath: `/Users/admin/Documents/My Workspace/we-humanity-wf3c/renders/${filename}`,
      linkedinCaption,
      instagramCaption,
      xThread
    },
    pairedItem: { item: 0 }
  });
}
return out;
